Running command: cat > /workspace/test_harness.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libmdnsd/mdnsd.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *data = (unsigned char *)malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    struct message m;
    memset(&m, 0, sizeof(struct message));

    unsigned char *dataCopy = (unsigned char *)malloc(size);
    memcpy(dataCopy, data, size);

    bool success = message_parse(&m, dataCopy, size);

    free(dataCopy);

    if (!success) {
        printf("message_parse returned false\n");
        free(data);
        return 0;
    }

    mdns_daemon_t *d = mdnsd_new(QCLASS_IN, 1000);
    in_addr_t addr = 0;
    mdnsd_in(d, &m, addr, 2000);
    mdnsd_free(d);

    free(data);
    printf("Success\n");
    return 0;
}
EOF

